package store.cadera.cdrjobs.listener;
import net.kyori.adventure.text.Component;import org.bukkit.Material;import org.bukkit.block.Block;import org.bukkit.block.data.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.BlockBreakEvent;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.api.*;import store.cadera.cdrjobs.api.event.ProfessionActionEvent;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import java.util.*;
public final class FarmerListener implements Listener{private static final Set<Material>REPLANT=EnumSet.of(Material.WHEAT,Material.CARROTS,Material.POTATOES,Material.BEETROOTS,Material.NETHER_WART),RARE=EnumSet.of(Material.MELON,Material.PUMPKIN,Material.NETHER_WART,Material.COCOA);private final CdrJobsPlugin plugin;private final ProfessionStore store;private final ProgressionService progression;private final FarmerService farmer;private final LevelService levels;private Map<Material,Integer>xp=new HashMap<>();public FarmerListener(CdrJobsPlugin p,Database d,ProfessionStore s,ProgressionService pr,FarmerService f,LevelService l){plugin=p;store=s;progression=pr;farmer=f;levels=l;refreshXpMap();}public void refreshXpMap(){xp=plugin.loadActivityXp("farmer.xp");}
@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void harvest(BlockBreakEvent e){if(!plugin.getConfig().getBoolean("farmer.enabled",true))return;Block b=e.getBlock();Integer base=xp.get(b.getType());if(base==null||!mature(b))return;long cd=Math.max(0,plugin.getConfig().getLong("farmer.anti-exploit.location-cooldown-seconds",30))*1000;if(!store.tryClaimLocation(b.getLocation(),"farmer_harvest",cd))return;Player p=e.getPlayer();Material original=b.getType();BlockData old=b.getBlockData().clone();farmer.recordHarvest(p,RARE.contains(original));plugin.getServer().getPluginManager().callEvent(new ProfessionActionEvent(p,JobType.FARMER,ProfessionActionType.HARVEST_CROP,1));long amount=farmer.applyXpModifiers(p,Math.max(1,Math.round(base*Math.max(0,plugin.getConfig().getDouble("farmer.xp-multiplier",1)))));JobProgress pr=progression.addXp(p,JobType.FARMER,amount);if(farmer.autoReplant(p)&&REPLANT.contains(original))plugin.getServer().getScheduler().runTaskLater(plugin,()->{if(b.getType()!=Material.AIR)return;b.setType(original,false);BlockData data=b.getBlockData();if(data instanceof Ageable a){a.setAge(0);b.setBlockData(a,false);}else b.setBlockData(old,false);},1);if(plugin.getConfig().getBoolean("settings.actionbar-xp",true)){long req=levels.xpRequiredForNextLevel(pr.level());p.sendActionBar(Component.text(pr.level()>=levels.maxLevel()?"✦ Verdant Keeper Lv."+levels.maxLevel()+" • MAX":"✦ Verdant +"+amount+" XP • Lv."+pr.level()+" • "+pr.xp()+"/"+req));}}
private boolean mature(Block b){if(b.getType()==Material.MELON||b.getType()==Material.PUMPKIN)return true;return b.getBlockData() instanceof Ageable a&&a.getAge()>=a.getMaximumAge();}
}
